164	// Validates an output reference of the shape
165	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
166	// reference itself must be a non-array object, nodeId must name an action
167	// node in this definition (matched as a whole string — dots are literal),
168	// and path, when present, follows the same segment rules as input paths.
169	function compileOutputReference(ref, nodes, label) {
170	  if (!isUsableObject(ref)) {
171	    throw new Error(`${label}: output reference must be a non-array object`);
172	  }
173	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
174	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
175	  }
176	  const target = nodes.get(ref.nodeId);
177	  if (!target) {
178	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
179	  }
180	  if (target.type !== 'action') {
181	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
182	  }
183	  let segments = [];
184	  if (Object.hasOwn(ref, 'path')) {
185	    segments = parsePathSegments(ref.path, `${label} path`);
186	  }
187	  return { nodeId: ref.nodeId, segments };
188	}
