323	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
324	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
325	
326	function isIntegerIn(value, min, max) {
327	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
328	}
