330	// A retry block is either absent (one attempt, no waiting) or present with all
331	// four parameters together, each within the same ranges the engine enforces
332	// for business action retries and compensation retries alike.
333	function compileRetry(config, label) {
334	  if (!isUsableObject(config)) {
335	    throw new Error(`${label}: retry must be an object`);
336	  }
337	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
338	  if (missing.length > 0) {
339	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
340	  }
341	  if (!isIntegerIn(config.attempts, 1, 10)) {
342	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
343	  }
344	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
345	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
346	  }
347	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
348	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
349	  }
350	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
351	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
352	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
353	  }
354	  if (config.maxDelayMs < config.initialDelayMs) {
355	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
356	  }
357	  return {
358	    attempts: config.attempts,
359	    initialDelayMs: config.initialDelayMs,
360	    backoffFactor: config.backoffFactor,
361	    maxDelayMs: config.maxDelayMs,
362	  };
363	}
364	
365	// An action node either keeps the legacy `message` behavior, names a business
366	// operation the caller supplies at run time, and/or declares a compensation
367	// operation that undoes its business effect. Both retry blocks are optional
368	// and, absent, mean exactly one attempt with no waiting.
369	function compileAction(node) {
370	  let name = null;
371	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
372	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
373	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
374	    }
375	    name = node.operation;
376	  }
377	
378	  let retry = { ...DEFAULT_RETRY };
379	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
380	    if (!name) {
381	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
382	    }
383	    retry = compileRetry(node.retry, `action node ${node.id}`);
384	  }
385	
386	  let compensation = null;
387	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
388	    if (!isUsableObject(node.compensation)) {
389	      throw new Error(`action node ${node.id}: compensation must be an object`);
390	    }
391	    if (!name) {
392	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
393	    }
394	    const config = node.compensation;
395	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
396	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
397	    }
398	    let compRetry = { ...DEFAULT_RETRY };
399	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
400	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
401	    }
402	    compensation = { name: config.operation, retry: compRetry };
403	  }
404	
405	  // A legacy message action (no operation) is validated through the single
406	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
407	  // action-specific wording, that end-node results use — covering every
408	  // message action including ones on untaken branches and entry-unreachable
409	  // ones. An action that names an operation ignores its message entirely, so
410	  // an unused uncloneable or shared-memory message is never rejected for it.
411	  // The gate only proves the message was safe as it was then; the same rule
412	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
413	  if (name === null) {
414	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
415	  }
416	
417	  return { name, retry, compensation };
418	}
419	
420	// The two failure kinds a node-configured value can produce, shared by
421	// definition validation (assertConfiguredCopy below) and the execution-time
422	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
423	// all, or it clones but the clone retains shared memory. Uncloneability takes
424	// precedence when a value carries both, at both moments. Each node kind keeps
425	// its own wording — an action's message and an end node's result fail with the
426	// node-specific text the entries already exposed — and its own default for a
427	// value that is absent, undefined or null (action:<node id> for a legacy
428	// message; null for an end result), while "", 0 and false pass through
429	// untouched for both.
430	const ACTION_MESSAGE_COPY_ERRORS = {
431	  uncloneable: nodeId =>
432	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
433	  sharedMemory: nodeId =>
434	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
435	};
436	const END_RESULT_COPY_ERRORS = {
437	  uncloneable: nodeId =>
438	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
439	  sharedMemory: nodeId =>
440	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
441	};
442	
443	// The single independent-copy rule for a value a node configures — a legacy
444	// action's `message` and an end node's `result` both go through here, so the
445	// cloneability and retained-shared-memory rules are maintained in exactly one
446	// place and the two node kinds can never drift apart. It is invoked at two
447	// moments, and each moment keeps its original root-read protocol:
448	//
449	//  1. At validation time (assertConfiguredCopy), for every such node in the
450	//     definition — including nodes on untaken branches and nodes the entry
451	//     cannot reach — so a statically invalid value is rejected before any
452	//     node, business operation or compensation can run. An absent own
453	//     property is not read at all; the gate performs the first root read and
454	//     only an own, defined value reaches the clone, which performs the root's
455	//     second read itself (a throwing root accessor propagates from the gate
456	//     exactly as before).
457	//  2. At the node's own execution moment (readConfiguredCopy), against the
458	//     value actually about to be saved: the root is read exactly once and the
459	//     value that read produced is cloned, so validation cannot pin the result
460	//     — an enumerable getter's later answer and a preceding business
461	//     operation's or another activated branch's mutation are both captured.
462	//
463	// At either moment every nested enumerable accessor is read only by
464	// structuredClone's own read — there is no separate inspection pass over the
465	// original, so a getter's return order is never disturbed and the value the
466	// clone's read produced is both what is judged and what is saved (a legal
467	// value whose getter answers with a different ordinary value at execution
468	// time records that fresh value rather than the stale validation-time one). A
469	// root getter that throws on execution's single read, a nested getter that
470	// throws while the clone reads it, and a value that cannot be cloned at all
471	// (a bare function) all surface as the same uncloneable error.
472	//
473	// The copy itself is produced by independentCopy — the one clone-then-judge
474	// rule every saved value in this engine goes through (see its comment for why
475	// cloning must precede the shared-memory traversal and why uncloneability
476	// takes precedence). Only the wording of the failure is node-specific here.
477	//
478	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
479	// rather than recorded as a run status: the synchronous entry propagates it
480	// and the asynchronous entry's rejected Promise carries it. It is never an
481	// action_failed — neither node kind has a retry budget — it neither consumes
482	// business-action retries nor triggers compensation, and no output/result is
483	// recorded for the node. At execution, an absent, undefined or null value
484	// becomes `absentValue` (action:<node id> for messages, null for results),
485	// while "", 0 and false pass through untouched.
486	function configuredCopy(node, property, errors, options) {
487	  const validation = options !== undefined && options.validation === true;
488	
489	  if (validation) {
490	    // Preserve the validation gate exactly: no read at all for a missing own
491	    // property, one unguarded gate read (a throwing root accessor propagates
492	    // raw, as the former per-node gates did), and an undefined value is left
493	    // to execution. The structuredClone argument evaluation is the root's
494	    // second — and final — read this moment; the clone itself traverses that
495	    // captured value (firing nested getters once), so no read the original
496	    // gate made is added or removed.
497	    if (!Object.hasOwn(node, property)) return;
498	    const gated = node[property];
499	    if (gated === undefined) return;
500	    const copy = independentCopy(node[property]);
501	    if (!copy.ok) throw new Error(errors[copy.reason](node.id));
502	    return;
503	  }
504	
505	  // Execution: the root value's single read. An absent, undefined or null
506	  // value takes the node kind's default (action:<node id> for messages, null
